describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const line: CartLine = {
        product: { id: "a", name: "A", unitPriceCents: 100 },
        quantity: 2,
      };
      expect(calc.computeShippingCents([line], 5000)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(300);
    });

    it("selects first bracket at exact boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(300);
    });

    it("selects second bracket when weight exceeds first", () => {
      expect(calc.computeShippingCents([makeLine("a", 501)], 5000)).toBe(700);
    });

    it("selects second bracket at its boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 2000)], 5000)).toBe(700);
    });

    it("selects third bracket", () => {
      expect(calc.computeShippingCents([makeLine("a", 2001)], 5000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(calc.computeShippingCents([makeLine("a", 6000)], 5000)).toBe(2000);
    });

    it("sums weight across multiple lines", () => {
      // 300 * 2 = 600g total → second bracket
      const lines = [makeLine("a", 300, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });

    it("defaults overflow to heaviest bracket cost when not specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      expect(noOverflow.computeShippingCents([makeLine("a", 5000)], 5000)).toBe(
        900,
      );
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      expect(unordered.computeShippingCents([makeLine("a", 400)], 5000)).toBe(300);
      expect(unordered.computeShippingCents([makeLine("a", 1500)], 5000)).toBe(700);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product, CartLine } from "../src/product.ts";
