  });

  it("throws InventoryError when item is unavailable", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(1);
      expect(err.name).toBe("InventoryError");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValue({ available: true, availableQuantity: 2 }),
    };
    const cart = new Cart();
    cart.add(productA, 5);
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(2);
    }
  });

  it("passes when availableQuantity >= requested", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const cart = new Cart();
    cart.add(productA, 5);
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(5000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000, no discount → taxable 1000
    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    expect(result.totals.taxCents).toBe(100); // 10% of 1000
  });

  it("async tax uses discounted subtotal", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(400),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ discountPolicy, region: "FR" });
    cart.add(productA, 1); // subtotal 1000, discount 400, taxable 600
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(60); // 10% of 600
    expect(result.totals.discountCents).toBe(400);
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(productA, 2);
    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // subtotal: 500 * 2 = 1000, no discount, tax 5% of 1000 = 50, shipping 300
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.taxCents).toBe(50);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(1350);
  });

  it("propagates priceFetcher rejection", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch failed");
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });
});

